public static void main(String[] args) {
    var sc = new Scanner(System.in);
    int n = sc.nextInt();
    int m = sc.nextInt();
    int[] p = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        p[i] = i;
    }
    long ret = 0;
    int mm = m;

    var mp = new HashMap<Integer, Long>();
    var se = new TreeSet<Integer>();
    while (m-- != 0) {
        int x = sc.nextInt();
        int y = sc.nextInt();
        p[find(p, y)] = find(p, x);
    }

    for (int i = 1; i <= n; i++) {
        int x = find(p, i);
        if (!mp.containsKey(x)) {
            mp.put(x, 0L);
        }
        long t = mp.get(x) + 1;
        mp.put(x, t);
        se.add(x);
    }
    for (int i : se) {
        long tt = mp.get(i);
        long t2 = mp.get(i) - 1;

        ret += tt * t2 / 2;
    }
    ret -= mm;
    System.out.print(ret);
}

private static int find(int[] p, int x) {
    if (p[x] != x) {
        p[x] = find(p, p[x]);
    }
    return p[x];
}
